<?php
namespace Dth\Crm\Services;
use Dth\Crm\Models\{Customer,CustomerAssignment,CustomerDistributionBatch,CustomerDistributionItem,Staff}; use Dth\Crm\Support\CodeGenerator; use Illuminate\Support\Facades\DB;
final class CustomerDistributionService {public function __construct(private CodeGenerator $codes){}
 public function distribute(array $customerIds,?int $actor=null):CustomerDistributionBatch{return DB::transaction(function()use($customerIds,$actor){$staff=Staff::where('employment_status','active')->get();$batch=CustomerDistributionBatch::create(['batch_code'=>$this->codes->make('DIST'),'batch_type'=>'customer','strategy'=>'round_robin','status'=>'processing','total_items'=>count($customerIds),'created_by_user_id'=>$actor]);if($staff->isEmpty()){ $batch->update(['status'=>'failed']); return $batch;} $i=0;foreach(Customer::whereKey($customerIds)->get() as $customer){$s=$staff[$i++%$staff->count()];CustomerAssignment::where('customer_id',$customer->id)->where('status','active')->update(['status'=>'ended','ends_at'=>now()]);$a=CustomerAssignment::create(['customer_id'=>$customer->id,'staff_id'=>$s->id,'assignment_type'=>'owner','status'=>'active','reason'=>'rebalance','assigned_by_user_id'=>$actor,'starts_at'=>now()]);CustomerDistributionItem::create(['distribution_batch_id'=>$batch->id,'customer_id'=>$customer->id,'assigned_staff_id'=>$s->id,'assignment_type'=>'owner','result_status'=>'assigned']);}$batch->update(['processed_items'=>$i,'status'=>'completed']);return $batch;});}
}
